#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("ciag.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int cnt = 0;
    for (int i = 0; i < (int)dane.size() - 1; i++) {
        int diff = dane[i] - dane[i + 1];
        if (diff < 0) diff = -diff;
        if (diff > 5) cnt++;
    }
    cout << "Pary sasiadow o roznicy > 5: " << cnt << endl;
    return 0;
}
